<script setup>
import {computed} from 'vue';import {sources,binsFor,clock} from './data';import {useTimeline} from './useTimeline';import TimeAxis from './TimeAxis.vue';
const {state,filtered,inspect}=useTimeline();
const bins=computed(()=>binsFor(filtered.value,state.start,state.end,60));
const max=computed(()=>Math.max(1,...bins.value.map(b=>b.count)));
const paths=computed(()=>sources.map((s,j)=>{const upper=bins.value.map((b,i)=>[i/59*1000,300-sources.slice(0,j+1).reduce((a,x)=>a+b.bySource[x.id],0)/max.value*250]);const lower=bins.value.map((b,i)=>[i/59*1000,300-sources.slice(0,j).reduce((a,x)=>a+b.bySource[x.id],0)/max.value*250]).reverse();return {...s,d:'M'+[...upper,...lower].map(p=>p.join(',')).join(' L')+' Z'}}));
</script><template><div class="river-wrap" dir="ltr"><span class="chart-unit">רשומות לחלון · שיא {{max}}</span><svg viewBox="0 0 1000 340" role="img" aria-label="נפח פעילות לאורך זמן לפי מערכת"><line v-for="y in [50,175,300]" :key="y" x1="0" x2="1000" :y1="y" :y2="y" class="gridline"/><path v-for="s in paths" :key="s.id" :d="s.d" :fill="s.color" opacity=".75"/><g v-for="(b,i) in bins" :key="i"><circle v-if="b.alert" :cx="i/59*1000" cy="322" r="4" fill="#edb280"/><rect :x="i/60*1000" y="0" width="16.7" height="340" class="svg-hit" tabindex="0" role="button" :aria-label="clock(b.start)+' '+b.count+' רשומות'" @click="inspect(b.start,b.end)" @keydown.enter="inspect(b.start,b.end)"><title>{{clock(b.start)}} · {{b.count}} רשומות · {{b.alert}} חריגות</title></rect></g></svg><TimeAxis :start="state.start" :end="state.end"/></div><div class="source-legend"><span v-for="s in sources" :key="s.id"><i :style="{background:s.color}"></i>{{s.label}}</span></div><p class="plot-note">הנקודות הכתומות מסמנות חלונות עם חריגות, גם כאשר נפח הפעילות הכולל כמעט לא השתנה.</p></template>